From 5db5aecf848bef804617420455481b7e1be2ae53 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:47:31 +0100
Subject: [PATCH] plasmaquick/popupplasmawindow: don't let clicks through popup
 gaps

Clicks in a floating popup's gaps reached the window below. On Wayland,
a transparent child window now covers gaps up to the floating margin and
closes an unpinned popup on press; larger gaps stay as they were.

BUG: 517132
---
 src/plasmaquick/popupplasmawindow.cpp | 81 +++++++++++++++++++++++++++
 1 file changed, 81 insertions(+)

diff --git a/src/plasmaquick/popupplasmawindow.cpp b/src/plasmaquick/popupplasmawindow.cpp
index 3230442c9..87e4ab106 100644
--- a/src/plasmaquick/popupplasmawindow.cpp
+++ b/src/plasmaquick/popupplasmawindow.cpp
@@ -10,6 +10,8 @@

 #include "debug_p.h"
 #include <QGuiApplication>
+#include <QPainter>
+#include <QRasterWindow>
 #include <QScreen>
 #include <qnamespace.h>
 #include <qtmetamacros.h>
@@ -23,6 +25,33 @@
 namespace PlasmaQuick
 {

+// Transparent child surface covering the gap between a popup and its panel or the screen edge,
+// so that clicks there don't reach the window below
+class PopupGapWindow : public QRasterWindow
+{
+public:
+    PopupGapWindow(QWindow *popup)
+        : QRasterWindow(popup)
+    {
+        QSurfaceFormat format;
+        format.setAlphaBufferSize(8);
+        setFormat(format);
+        setFlag(Qt::WindowDoesNotAcceptFocus);
+    }
+
+protected:
+    void paintEvent(QPaintEvent *) override
+    {
+        QPainter painter(this);
+        painter.setCompositionMode(QPainter::CompositionMode_Source);
+        painter.fillRect(QRect(QPoint(0, 0), size()), Qt::transparent);
+    }
+    void mousePressEvent(QMouseEvent *) override
+    {
+        parent()->setVisible(false);
+    }
+};
+
 class PopupPlasmaWindowPrivate
 {
 public:
@@ -33,6 +62,7 @@ public:
     void updatePosition();
     void updatePosition(const QPoint &position);
     void updateBorders(const QRect &globalPosition);
+    void updateGapWindow(const QRect &globalPosition);
     void updateVisualParentWindow();

     void handleFocusChanged();
@@ -40,6 +70,7 @@ public:
     PopupPlasmaWindow *q;
     QPointer<QQuickItem> m_visualParent;
     QPointer<QQuickWindow> m_visualParentWindow;
+    PopupGapWindow *m_gapWindow = nullptr;
     PopupPlasmaWindow::RemoveBorders m_removeBorderStrategy = PopupPlasmaWindow::Never;
     bool m_needsReposition = false;
     bool m_floating = false;
@@ -181,6 +212,7 @@ void PopupPlasmaWindowPrivate::updatePosition()
     }

     updateBorders(popupPosition);
+    updateGapWindow(popupPosition);
 }

 void PopupPlasmaWindowPrivate::updatePosition(const QPoint &position)
@@ -260,6 +292,51 @@ void PopupPlasmaWindowPrivate::updateBorders(const QRect &globalPosition)
     q->setBorders(enabledBorders);
 }

+void PopupPlasmaWindowPrivate::updateGapWindow(const QRect &globalPosition)
+{
+    if (!m_gapWindow) {
+        return;
+    }
+
+    QMargins gaps;
+    QScreen *screen = QGuiApplication::screenAt(globalPosition.center());
+    if (screen && m_margin > 0 && !m_floating && m_hideOnWindowDeactivate) {
+        const QRect screenGeometry = screen->geometry();
+        auto screenGap = [this](int distance) {
+            return distance <= m_margin ? std::max(distance, 0) : 0;
+        };
+        gaps = QMargins(screenGap(globalPosition.left() - screenGeometry.left()),
+                        screenGap(globalPosition.top() - screenGeometry.top()),
+                        screenGap(screenGeometry.right() - globalPosition.right()),
+                        screenGap(screenGeometry.bottom() - globalPosition.bottom()));
+        switch (m_effectivePopupDirection) {
+        case Qt::TopEdge:
+            gaps.setBottom(m_margin);
+            break;
+        case Qt::BottomEdge:
+            gaps.setTop(m_margin);
+            break;
+        case Qt::LeftEdge:
+            gaps.setRight(m_margin);
+            break;
+        case Qt::RightEdge:
+            gaps.setLeft(m_margin);
+            break;
+        }
+    }
+
+    if (gaps.isNull()) {
+        m_gapWindow->hide();
+        return;
+    }
+
+    const QRect popupRect(QPoint(0, 0), globalPosition.size());
+    const QRect gapRect = popupRect.marginsAdded(gaps);
+    m_gapWindow->setGeometry(gapRect);
+    m_gapWindow->setMask(QRegion(gapRect.translated(-gapRect.topLeft())) - QRegion(popupRect.translated(-gapRect.topLeft())));
+    m_gapWindow->show();
+}
+
 void PopupPlasmaWindowPrivate::updateVisualParentWindow()
 {
     if (m_visualParentWindow) {
@@ -308,6 +385,7 @@ PopupPlasmaWindow::PopupPlasmaWindow(const QString &svgPrefix)
 {
     if (KWindowSystem::isPlatformWayland()) {
         PlasmaShellWaylandIntegration::get(this)->setTakesFocus(true);
+        d->m_gapWindow = new PopupGapWindow(this);
     }

     QObject::connect(static_cast<QGuiApplication *>(QCoreApplication::instance()), &QGuiApplication::focusWindowChanged, this, [this]() {
@@ -408,6 +486,9 @@ void PopupPlasmaWindow::setHideOnWindowDeactivate(bool hideOnWindowDeactivate)
         return;
     }
     d->m_hideOnWindowDeactivate = hideOnWindowDeactivate;
+    if (isVisible()) {
+        d->updateGapWindow(geometry());
+    }
     Q_EMIT hideOnWindowDeactivateChanged();
 }

